AssistantMessageToolRequest(name='create', tool_call_id='tooluse_IA9tkxZRTjVbVolZi3fI5h', arguments={'file_text': "/* Root Variables */
:root {
  --color-bg-primary: #0f1419;
  --color-bg-secondary: #1a1f2e;
  --color-bg-tertiary: #242a3d;
  --color-text-primary: #ffffff;
  --color-text-secondary: #b0b8cc;
  --color-text-tertiary: #7a8299;
  --color-accent: #00d9ff;
  --color-accent-hover: #00b8d4;
  --color-error: #ff4757;
  --color-success: #2ed573;
  --color-warning: #ffa502;
  --color-border: #2d3748;
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
  --transition-fast: 150ms ease-in-out;
  --transition-base: 250ms ease-in-out;
  --transition-slow: 350ms ease-in-out;
}

/* Accessibility: Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Forced Colors Mode Support */
@media (forced-colors: active) {
  * {
    border-color: CanvasText;
  }
}

/* Reset and Base Styles */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.6;
  letter-spacing: 0.3px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.5px;
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }
h6 { font-size: 1rem; }

p {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: color var(--transition-base);
}

a:hover,
a:focus-visible {
  color: var(--color-accent-hover);
  outline: none;
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  text-decoration: none;
  z-index: 9999;
  transform: translateY(-100%);
  transition: transform var(--transition-base);
  font-weight: 600;
}

.skip-link:focus-visible {
  transform: translateY(0);
  outline: 2px solid var(--color-accent-hover);
  outline-offset: 2px;
}

/* Focus Visible Outline */
*:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Screen Reader Only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Header */
.header {
  background-color: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(10px);
  background-color: rgba(26, 31, 46, 0.95);
}

.header-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg) var(--spacing-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-lg);
}

.logo-section {
  flex-shrink: 0;
}

.site-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -1px;
}

.site-tagline {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin: 0;
}

.primary-nav {
  flex-grow: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-sm);
  color: var(--color-text-primary);
}

.hamburger {
  display: block;
  width: 24px;
  height: 2px;
  background-color: currentColor;
  margin: 6px 0;
  transition: transform var(--transition-base);
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-2xl);
  margin: 0;
  padding: 0;
}

.nav-link {
  color: var(--color-text-secondary);
  font-weight: 500;
  transition: color var(--transition-base);
  position: relative;
  padding-bottom: 4px;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link:focus-visible::after {
  width: 100%;
}

.header-actions {
  display: flex;
  gap: var(--spacing-lg);
  flex-shrink: 0;
}

.icon-button {
  background: none;
  border: none;
  color: var(--color-text-secondary);
  cursor: pointer;
  padding: var(--spacing-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition-base);
  border-radius: var(--radius-md);
}

.icon-button:hover,
.icon-button:focus-visible {
  color: var(--color-accent);
  background-color: var(--color-bg-tertiary);
}

/* Responsive Header */
@media (max-width: 768px) {
  .header-container {
    flex-wrap: wrap;
    padding: var(--spacing-md) var(--spacing-lg);
  }

  .nav-toggle {
    display: block;
  }

  .nav-menu {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    gap: var(--spacing-md);
    background-color: var(--color-bg-secondary);
    padding: var(--spacing-lg);
    border-bottom: 1px solid var(--color-border);
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
  }

  .nav-menu.active {
    max-height: 300px;
  }

  .primary-nav {
    position: relative;
    width: 100%;
    order: 3;
  }
}

/* Hero Section */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-3xl);
  align-items: center;
  padding: var(--spacing-3xl) var(--spacing-lg);
  background: linear-gradient(135deg, rgba(0, 217, 255, 0.1) 0%, rgba(0, 0, 0, 0.2) 100%);
  border-bottom: 1px solid var(--color-border);
}

.hero-content {
  padding: var(--spacing-xl) 0;
}

.hero-title {
  font-size: 3rem;
  margin-bottom: var(--spacing-lg);
  background: linear-gradient(135deg, var(--color-accent), #00ffff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-2xl);
}

.hero-image {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 400px;
}

@media (max-width: 1024px) {
  .hero {
    grid-template-columns: 1fr;
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .hero-image {
    height: 300px;
  }

  .hero-title {
    font-size: 2rem;
  }
}

/* Image Placeholders */
.image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-bg-secondary) 100%);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
}

/* Section Container */
.section-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-3xl) var(--spacing-lg);
}

.section-heading {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.section-subtitle {
  text-align: center;
  color: var(--color-text-tertiary);
  margin-bottom: var(--spacing-3xl);
}

/* Products Section */
.featured-section {
  background-color: var(--color-bg-primary);
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-2xl);
  margin-bottom: var(--spacing-3xl);
}

.product-card {
  background-color: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.product-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.product-image {
  position: relative;
  width: 100%;
  height: 240px;
  overflow: hidden;
  background-color: var(--color-bg-tertiary);
}

.product-image .image-placeholder {
  height: 100%;
  border-radius: 0;
  border: none;
}

.badge {
  position: absolute;
  top: var(--spacing-md);
  right: var(--spacing-md);
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  z-index: 10;
}

.badge.sale {
  background-color: var(--color-error);
}

.product-info {
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-name {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
}

.product-category {
  font-size: 0.875rem;
  color: var(--color-text-tertiary);
  text-transform: uppercase;
  margin-bottom: var(--spacing-md);
  font-weight: 500;
}

.product-description {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  font-size: 0.875rem;
}

.stars {
  color: var(--color-warning);
  letter-spacing: 2px;
}

.rating-count {
  color: var(--color-text-tertiary);
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-lg);
}

.current-price {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent);
}

.original-price {
  text-decoration: line-through;
  color: var(--color-text-tertiary);
  font-size: 0.875rem;
}

.add-to-cart-button {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  border: none;
  padding: var(--spacing-md) var(--spacing-lg);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all var(--transition-base);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.add-to-cart-button:hover,
.add-to-cart-button:focus-visible {
  background-color: var(--color-accent-hover);
  transform: scale(1.02);
}

.add-to-cart-button:active {
  transform: scale(0.98);
}

/* Buttons */
.cta-button,
.primary-button {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  border: 2px solid var(--color-accent);
  padding: var(--spacing-md) var(--spacing-2xl);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all var(--transition-base);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.cta-button:hover,
.primary-button:hover,
.cta-button:focus-visible,
.primary-button:focus-visible {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: scale(1.02);
}

.secondary-button {
  background-color: transparent;
  color: var(--color-accent);
  border: 2px solid var(--color-accent);
  padding: var(--spacing-md) var(--spacing-2xl);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all var(--transition-base);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.secondary-button:hover,
.secondary-button:focus-visible {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
}

.section-cta {
  text-align: center;
}

/* Deals Section */
.deals-section {
  background-color: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-2xl);
}

.deal-card {
  background-color: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  transition: all var(--transition-base);
}

.deal-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.deal-badge {
  position: absolute;
  top: var(--spacing-md);
  left: var(--spacing-md);
  background-color: var(--color-error);
  color: var(--color-text-primary);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 0.875rem;
  z-index: 10;
}

.deal-image {
  width: 100%;
  height: 200px;
  background-color: var(--color-bg-tertiary);
}

.deal-info {
  padding: var(--spacing-lg);
}

.deal-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
}

.deal-description {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
}

.deal-timer {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
}

.timer-label {
  color: var(--color-text-tertiary);
}

.timer-display {
  color: var(--color-error);
  font-weight: 700;
}

.deal-action-button {
  width: 100%;
  background-color: var(--color-bg-tertiary);
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  padding: var(--spacing-md) var(--spacing-lg);
  border-radius: var(--radius-md);
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-base);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 0.95rem;
}

.deal-action-button:hover,
.deal-action-button:focus-visible {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
}

/* Editorial Section */
.editorial-section {
  background-color: var(--color-bg-primary);
}

.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-2xl);
}

.editorial-card {
  display: flex;
  flex-direction: column;
  background-color: transparent;
  border: none;
  transition: all var(--transition-base);
}

.editorial-card:hover {
  transform: translateY(-4px);
}

.editorial-image {
  width: 100%;
  height: 220px;
  background-color: var(--color-bg-tertiary);
  border-radius: var(--radius-lg);
  margin-bottom: var(--spacing-lg);
  overflow: hidden;
  border: 1px solid var(--color-border);
}

.editorial-content {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.article-category {
  display: inline-block;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: var(--spacing-md);
  width: fit-content;
}

.editorial-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
  font-weight: 600;
  line-height: 1.4;
}

.editorial-excerpt {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
  flex-grow: 1;
}

.article-date {
  display: block;
  color: var(--color-text-tertiary);
  font-size: 0.875rem;
  margin-bottom: var(--spacing-md);
}

.read-more-link {
  display: inline-block;
  color: var(--color-accent);
  font-weight: 600;
  position: relative;
  padding-bottom: 2px;
}

.read-more-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.read-more-link:hover::after,
.read-more-link:focus-visible::after {
  width: 100%;
}

/* Newsletter Section */
.newsletter-section {
  background: linear-gradient(135deg, rgba(0, 217, 255, 0.15) 0%, rgba(0, 0, 0, 0.3) 100%);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.newsletter-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-3xl);
  align-items: center;
}

.newsletter-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.newsletter-heading {
  margin-bottom: var(--spacing-md);
}

.newsletter-subtitle {
  color: var(--color-text-secondary);
  font-size: 1.05rem;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.form-group {
  display: flex;
  gap: var(--spacing-sm);
}

.email-input {
  flex-grow: 1;
  background-color: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  color: var(--color-text-primary);
  padding: var(--spacing-md) var(--spacing-lg);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: all var(--transition-base);
}

.email-input:focus-visible {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(0, 217, 255, 0.1);
}

.email-input::placeholder {
  color: var(--color-text-tertiary);
}

.subscribe-button {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  border: none;
  padding: var(--spacing-md) var(--spacing-2xl);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all var(--transition-base);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.subscribe-button:hover,
.subscribe-button:focus-visible {
  background-color: var(--color-accent-hover);
  transform: scale(1.02);
}

.form-help-text {
  font-size: 0.85rem;
  color: var(--color-text-tertiary);
  margin: 0;
}

@media (max-width: 768px) {
  .newsletter-container {
    grid-template-columns: 1fr;
  }

  .form-group {
    flex-direction: column;
  }

  .subscribe-button {
    width: 100%;
  }
}

/* Footer */
.footer {
  background-color: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-3xl) var(--spacing-lg) var(--spacing-2xl);
}

.footer-container {
  max-width: 1400px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-3xl);
  margin-bottom: var(--spacing-2xl);
}

.footer-column {
  display: flex;
  flex-direction: column;
}

.footer-heading {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--spacing-lg);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.footer-links,
.social-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.footer-link,
.social-link {
  color: var(--color-text-secondary);
  transition: color var(--transition-base);
  font-size: 0.95rem;
}

.footer-link:hover,
.social-link:hover,
.footer-link:focus-visible,
.social-link:focus-visible {
  color: var(--color-accent);
}

.footer-bottom {
  max-width: 1400px;
  margin: 0 auto;
  padding-top: var(--spacing-2xl);
  border-top: 1px solid var(--color-border);
  text-align: center;
}

.copyright {
  color: var(--color-text-tertiary);
  font-size: 0.875rem;
  margin: 0;
}

/* Responsive Design - Tablets */
@media (max-width: 1024px) {
  :root {
    font-size: 15px;
  }

  .products-grid {
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: var(--spacing-lg);
  }

  .section-container {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }
}

/* Responsive Design - Mobile */
@media (max-width: 640px) {
  :root {
    font-size: 14px;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.25rem; }

  .hero {
    grid-template-columns: 1fr;
    padding: var(--spacing-2xl) var(--spacing-lg);
    gap: var(--spacing-2xl);
  }

  .hero-title {
    font-size: 1.75rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .products-grid {
    grid-template-columns: 1fr;
  }

  .deals-grid {
    grid-template-columns: 1fr;
  }

  .editorial-grid {
    grid-template-columns: 1fr;
  }

  .section-container {
    padding: var(--spacing-2xl) var(--spacing-md);
  }

  .footer-container {
    gap: var(--spacing-2xl);
  }
}

/* Contrast and Forced Colors */
@media (forced-colors: active) {
  .product-card,
  .deal-card,
  .editorial-card {
    border: 1px solid CanvasText;
  }

  .badge,
  .badge.sale,
  .cta-button,
  .primary-button,
  .add-to-cart-button,
  .subscribe-button {
    border: 2px solid CanvasText;
  }

  .hero-title {
    -webkit-text-fill-color: CanvasText;
  }
}

/* High Contrast Mode */
@media (prefers-contrast: more) {
  --color-accent: #00ffff;
  --color-accent-hover: #00e6e6;
  --color-text-secondary: #d0d8ec;
}
