const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  const results = await new AxeBuilder({ page }).analyze();

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpWarnings = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => ({
        target: n.target,
        html: n.html
      }))
    })),
    best_practice: bpWarnings.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
