  console.log(`URL: file://${htmlPath}`);
  console.log(`Test Time: ${new Date().toISOString()}\n`);

  console.log(`Violations: ${results.violations.length}`);
  console.log(`Passes: ${results.passes.length}`);
  console.log(`Incomplete: ${results.incomplete.length}`);
  console.log(`Inapplicable: ${results.inapplicable.length}\n`);

  if (results.violations.length > 0) {
    console.log('VIOLATIONS:');
    results.violations.forEach(v => {
      console.log(`  - ${v.id} (${v.impact}): ${v.description}`);
      v.nodes.forEach(n => console.log(`    ${n.target}`));
    });
  }

  if (results.incomplete.length > 0) {
    console.log('\nINCOMPLETE (Manual Review Needed):');
    results.incomplete.forEach(v => {
      console.log(`  - ${v.id}: ${v.description}`);
      v.nodes.forEach(n => console.log(`    ${n.target}`));
    });
  }

  process.exit(results.violations.length > 0 ? 1 : 0);
})();
