  width: 24px;
  height: 2px;
  background-color: currentColor;
  margin: 6px 0;
  transition: transform var(--transition-base);
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-2xl);
  margin: 0;
  padding: 0;
}

.nav-link {
  color: var(--color-text-secondary);
  font-weight: 500;
  transition: color var(--transition-base);
  position: relative;
  padding-bottom: 4px;
}

.nav-link::after {
