}

.product-name {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
}

.product-category {
  font-size: 0.875rem;
  color: var(--color-text-tertiary);
  text-transform: uppercase;
  margin-bottom: var(--spacing-md);
  font-weight: 500;
}

.product-description {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  font-size: 0.875rem;
}

.stars {
  color: var(--color-accent);
  letter-spacing: 2px;
}

.rating-count {
  color: var(--color-text-tertiary);
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-lg);
}

.current-price {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent);
}

.original-price {
  text-decoration: line-through;
  color: var(--color-text-tertiary);
  font-size: 0.875rem;
}

.add-to-cart-button {
  background-color: var(--color-accent);
  color: var(--color-bg-primary);
  border: none;
  padding: var(--spacing-md) var(--spacing-lg);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.95rem;
