  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: var(--spacing-md);
  width: fit-content;
}

.editorial-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
  font-weight: 600;
  line-height: 1.4;
}

