const getLuminance = (r, g, b) => {
  const [rs, gs, bs] = [r, g, b].map(x => {
    x = x / 255;
    return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
};

const getContrast = (fg, bg) => {
  const l1 = getLuminance(fg.r, fg.g, fg.b);
  const l2 = getLuminance(bg.r, bg.g, bg.b);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
};

const colors = {
  error: { r: 255, g: 71, b: 87 },
  white: { r: 255, g: 255, b: 255 },
  oldTertiary: { r: 122, g: 130, b: 153 },
  newTertiary: { r: 139, g: 149, b: 174 },
  bg: { r: 15, g: 20, b: 25 },
};

console.log('Contrast Ratios:\n');
console.log(`Error (red) + White: ${getContrast(colors.error, colors.white).toFixed(2)}:1`);
console.log(`Old Tertiary + BG: ${getContrast(colors.oldTertiary, colors.bg).toFixed(2)}:1`);
console.log(`New Tertiary + BG: ${getContrast(colors.newTertiary, colors.bg).toFixed(2)}:1`);
EOF
