}

.logo-section {
  flex-shrink: 0;
}

.site-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -1px;
}

.site-tagline {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin: 0;
}

.primary-nav {
  flex-grow: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--spacing-sm);
  color: var(--color-text-primary);
}

.hamburger {
  display: block;
  width: 24px;
  height: 2px;
  background-color: currentColor;
  margin: 6px 0;
  transition: transform var(--transition-base);
}

.nav-menu {
  display: flex;
  list-style: none;
  gap: var(--spacing-2xl);
  margin: 0;
  padding: 0;
}

.nav-link {
  color: var(--color-text-secondary);
  font-weight: 500;
  transition: color var(--transition-base);
  position: relative;
  padding-bottom: 4px;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link:focus-visible::after {
  width: 100%;
}

.header-actions {
  display: flex;
  gap: var(--spacing-lg);
  flex-shrink: 0;
}

.icon-button {
  background: none;
  border: none;
  color: var(--color-text-secondary);
  cursor: pointer;
  padding: var(--spacing-sm);
  display: flex;
