  gap: var(--spacing-2xl);
  margin: 0;
  padding: 0;
}

.nav-link {
  color: var(--color-text-secondary);
  font-weight: 500;
  transition: color var(--transition-base);
  position: relative;
  padding-bottom: 4px;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link:focus-visible::after {
  width: 100%;
}

.header-actions {
  display: flex;
  gap: var(--spacing-lg);
  flex-shrink: 0;
}

.icon-button {
  background: none;
